-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"VIP-Sterne bleiben jetzt über eure Ladebildschirme hinweg erhalten. Gleichzeitige VIP-Aktualisierungen blockieren sich nicht mehr gegenseitig.","Ein Fehler wurde behoben, durch den Kartenmarkierungen verschwinden konnten, wenn eine Standortaktualisierung vorübergehend keine Koordinaten enthielt.","Die Zuverlässigkeit geteilter Aktualisierungen bei Kanaldrosselung wurde verbessert."},["title"]="Zuverlässigkeitsverbesserungen"}},["version"]="8.0.2",["welcome"]="Zuverlässigere Kartenmarkierungen und VIP-Erkennung."},["esES"]={["sections"]={{["items"]={"Las estrellas VIP ahora se conservan durante tus pantallas de carga, y las actualizaciones VIP simultáneas ya no se bloquean entre sí.","Se ha corregido un caso en el que los marcadores del mapa podían desaparecer si una actualización de ubicación no tenía coordenadas temporalmente.","Se ha mejorado la fiabilidad de las actualizaciones compartidas cuando el canal limita los envíos."},["title"]="Mejoras de fiabilidad"}},["version"]="8.0.2",["welcome"]="Marcadores del mapa e identificación VIP más fiables."},["esMX"]={["sections"]={{["items"]={"Las estrellas VIP ahora se conservan durante tus pantallas de carga, y las actualizaciones VIP simultáneas ya no se bloquean entre sí.","Se corrigió un caso en el que los marcadores del mapa podían desaparecer si una actualización de ubicación no tenía coordenadas temporalmente.","Se mejoró la confiabilidad de las actualizaciones compartidas cuando el canal limita los envíos."},["title"]="Mejoras de confiabilidad"}},["version"]="8.0.2",["welcome"]="Marcadores del mapa e identificación VIP más confiables."},["frFR"]={["sections"]={{["items"]={"Les étoiles VIP sont désormais conservées pendant vos écrans de chargement, et les mises à jour VIP simultanées ne se bloquent plus mutuellement.","Correction d’un cas où les marqueurs de carte pouvaient disparaître lorsqu’une mise à jour de position ne contenait temporairement aucune coordonnée.","Fiabilité améliorée des mises à jour partagées lorsque le canal limite les envois."},["title"]="Améliorations de la fiabilité"}},["version"]="8.0.2",["welcome"]="Des marqueurs de carte et une identification VIP plus fiables."},["itIT"]={["sections"]={{["items"]={"Le stelle VIP vengono ora mantenute durante le tue schermate di caricamento e gli aggiornamenti VIP simultanei non si bloccano più a vicenda.","Risolto un caso in cui gli indicatori sulla mappa potevano scomparire quando un aggiornamento della posizione era temporaneamente privo di coordinate.","Migliorata l’affidabilità degli aggiornamenti condivisi quando il canale limita gli invii."},["title"]="Miglioramenti all’affidabilità"}},["version"]="8.0.2",["welcome"]="Indicatori sulla mappa e identificazione VIP più affidabili."},["koKR"]={["sections"]={{["items"]={"이제 로딩 화면을 거쳐도 VIP 별 표시가 유지되며, 동시에 수신되는 VIP 업데이트가 서로를 차단하지 않습니다.","위치 업데이트에 일시적으로 좌표가 없을 때 지도 표시가 사라질 수 있던 문제를 수정했습니다.","채널 전송이 제한될 때 공유 업데이트의 안정성을 개선했습니다."},["title"]="안정성 개선"}},["version"]="8.0.2",["welcome"]="지도 표시와 VIP 식별의 안정성이 향상되었습니다."},["ptBR"]={["sections"]={{["items"]={"As estrelas VIP agora são preservadas durante suas telas de carregamento, e atualizações VIP simultâneas não bloqueiam mais umas às outras.","Corrigido um caso em que os marcadores do mapa podiam desaparecer quando uma atualização de localização ficava temporariamente sem coordenadas.","Melhorada a confiabilidade das atualizações compartilhadas quando o canal limita os envios."},["title"]="Melhorias de confiabilidade"}},["version"]="8.0.2",["welcome"]="Marcadores de mapa e identificação VIP mais confiáveis."},["ruRU"]={["sections"]={{["items"]={"Звёзды VIP теперь сохраняются при прохождении вами экранов загрузки, а одновременные обновления VIP больше не блокируют друг друга.","Исправлена ситуация, в которой метки на карте могли исчезать, если обновление местоположения временно не содержало координат.","Повышена надёжность передачи обновлений при ограничении отправки сообщений в канал."},["title"]="Повышение надёжности"}},["version"]="8.0.2",["welcome"]="Более надёжные метки на карте и распознавание VIP."},["zhCN"]={["sections"]={{["items"]={"现在经过加载画面后仍会保留 VIP 星标，同时到达的 VIP 更新也不会再互相阻挡。","修复了位置更新暂时没有坐标时，地图标记可能消失的问题。","提高了频道发送受限时共享更新的可靠性。"},["title"]="稳定性修复"}},["version"]="8.0.2",["welcome"]="地图标记和 VIP 识别更加稳定。"},["zhTW"]={["sections"]={{["items"]={"現在經過載入畫面後仍會保留 VIP 星號標記，同時到達的 VIP 更新也不會再互相阻擋。","修正了位置更新暫時沒有座標時，地圖標記可能消失的問題。","提高了頻道傳送受限時共用更新的可靠性。"},["title"]="穩定性修正"}},["version"]="8.0.2",["welcome"]="地圖標記與 VIP 識別更加穩定。"}}
